UPDATE pipeline_control
SET lease_until = now() + (#{leaseSeconds} * interval '1 second'),
    updated_at = now()
WHERE pipeline_name = #{pipelineName}
  AND phase = 'IMPORTING'
  AND owner_node = #{nodeId}

UPDATE pipeline_control
SET lease_until = now() + (#{leaseSeconds} * interval '1 second'),
    updated_at = now()
WHERE pipeline_name = #{pipelineName}
  AND phase = 'EXPORTING'
  AND owner_node = #{nodeId}
